window.CrateFilter=(songs,state)=>{
 const norm=x=>String(x||'').normalize('NFKC').toLowerCase(),words=norm(state.q).split(/\s+/).filter(Boolean);
 const result=songs.filter(s=>{const text=norm([s.title,...(s.aliases||[]),s.artist,s.album,s.scene,s.category,...(s.producers||[]),...(s.connections||[]),...(s.sounds||[]),...s.samples.map(x=>x.title+' '+x.artist)].join(' '));return (!state.collection||state.collection==='all'||(s.editorialCrates||[]).includes(state.collection))&&(!state.coast||state.coast==='all'||(state.coast==='other'?!(s.collections||[]).some(x=>x==='east'||x==='west'):(s.collections||[]).includes(state.coast)))&&words.every(w=>text.includes(w))&&(!state.region||s.region===state.region)&&(!state.era||String(Math.floor(s.year/10)*10)+'年代'===state.era)&&(!state.producer||(s.producers||[]).includes(state.producer))&&(!state.connection||(s.connections||[]).includes(state.connection))&&(!state.sound||(s.sounds||[]).includes(state.sound));});
 const tie=(a,b)=>a.artist.localeCompare(b.artist)||a.title.localeCompare(b.title);
 result.sort(state.sort==='title'?(a,b)=>a.title.localeCompare(b.title):state.sort==='artist'?tie:state.sort==='selection'?(a,b)=>a.addedOrder-b.addedOrder:(a,b)=>a.year-b.year||tie(a,b));return result;
};
